} else {
  // 卖出：超过持仓的部分不产生负股数，按实际持仓上限处理（防脏数据把成本算崩）
  const sh = Math.min(t.shares, p.shares);
  const avg = p.shares > 0 ? p.cost / p.shares : 0;
  const release = avg * sh;
  const shareFee = t.shares > 0 ? t.fee * (sh / t.shares) : 0; // 截断时费用按实成交比例分摊
  p.shares -= sh;
  p.cost -= release;
  if (p.shares <= 1e-9) { p.shares = 0; p.cost = 0; }
  p.realized += sh * t.price - shareFee - release;  // 用实成交股数 sh，防超额卖出把收益算虚高
  p.sellAmt += sh * t.price;
  p.feeSum += shareFee;
}

