} else {
  // 卖出：超过持仓的部分不产生负股数，按实际持仓上限处理（防脏数据把成本算崩）
  const sh = Math.min(t.shares, p.shares);
  const avg = p.shares > 0 ? p.cost / p.shares : 0;
  const release = avg * sh;
  p.shares -= sh;
  p.cost -= release;
  if (p.shares <= 1e-9) { p.shares = 0; p.cost = 0; }
  p.realized += t.shares * t.price - t.fee - release;
  p.sellAmt += t.shares * t.price;
  p.feeSum += t.fee;
}

