  st.push('<span class="badge ' + (bad ? 'b-red' : (gov === 'state' ? 'b-gold' : 'b-mut')) + '">' + (GOV_TXT[gov] || gov) + '</span>');
} else if (r.w > 0) {
  st.push('<span class="badge b-mut" title="config 未标注实控人类型，宪法第一条无法自动校验">实控未标注</span>');
}
if (r.shares > 0 && !r.price) st.push('<span class="badge b-mut">无行情</span>');
// 未持仓时区分「未建仓」（目标有仓位但从没买过）与「已清仓」（买过又卖光）
if (r.shares <= 0) {
  const _bought = (r.pos && r.pos.buyAmt > 0);
  if (r.w > 0 && !_bought) st.push('<span class="badge b-warn">待建仓</span>');
  else if (_bought) st.push('<span class="badge b-mut">已清仓</span>');
  else st.push('<span class="badge b-mut">未持有</span>');
}
if (r.w > 0 && r.shares > 0 && Math.abs(dev) >= (+RULES.dev_warn || 3))
  st.push('<span class="badge b-warn">' + (dev > 0 ? '超配 ' : '低配 ') + fmt(Math.abs(dev), 1) + '</span>');
if (r.shares > 0 && sharePct > (+RULES.max_single || 25))
  st.push('<span class="badge b-red">超单只上限</span>');
if (t.vol != null && r.shares > 0) {
  if (t.vol >= VOL_W) st.push('<span class="badge b-red">波动超线</span>');
  else if (t.vol >= VOL_W - 1) st.push('<span class="badge b-warn">逼近波动线</span>');
}
// 宪法条款时序：OCF/分红「连续两年」<1 或 支付率「连续两年」>80%
