if (r.shares > 0 && ocf2.length >= 2 && ocf2.every(v => v != null && v < (+RULES.ocf_min || 1)))
  st.push('<span class="badge b-red">连续两年分红无现金支撑</span>');
else if (t.ocfd != null && r.shares > 0 && t.ocfd < (+RULES.ocf_min || 1))
  st.push('<span class="badge b-red">分红无现金支撑</span>');
