  const VOL_W = +RULES.vol_warn || 25, OCF_MIN = +RULES.ocf_min || 1;
  rows.forEach(r => {
    if (!r.t || r.shares <= 0) return;
    if (r.t.vol != null && r.t.vol >= VOL_W)
      out.push(['bad', '×', esc(r.name) + ' 年化波动 ' + fmt(r.t.vol, 2) + '%，已触及卖出线 ' + VOL_W + '%。']);
    else if (r.t.vol != null && r.t.vol >= VOL_W - 1)
      out.push(['warn', '!', esc(r.name) + ' 年化波动 ' + fmt(r.t.vol, 2) + '%，逼近 ' + VOL_W + '% 卖出线。']);
    // 宪法条款：治理底线（实控人 family/foreign 一票否决）
    if (r.t.governance === 'family' || r.t.governance === 'foreign')
      out.push(['bad', '×', esc(r.name) + ' 实控人=' + (r.t.governance === 'family' ? '家族' : '外资') + '，违反宪法第一条（须国资控股），建议清出。']);
    // 宪法条款：「连续两年」OCF/分红 <1 或 支付率 >80%
    const ocf2 = Array.isArray(r.t.ocfd2y) ? r.t.ocfd2y : [];
    const pay2 = Array.isArray(r.t.payout2y) ? r.t.payout2y : [];
    if (ocf2.length >= 2 && ocf2.every(v => v != null && v < OCF_MIN))
      out.push(['bad', '×', esc(r.name) + ' OCF/分红连续两年 &lt; ' + OCF_MIN + '，分红非经营所得，违反宪法。']);
    if (pay2.length >= 2 && pay2.every(v => v != null && v > 80))
      out.push(['bad', '×', esc(r.name) + ' 支付率连续两年 &gt;80%，透支分红，违反宪法。']);
    if (r.t.ocfd != null && r.t.ocfd < OCF_MIN)
      out.push(['bad', '×', esc(r.name) + ' 经营现金流/分红 ' + fmt(r.t.ocfd, 2) + ' < ' + OCF_MIN + '，分红不是靠经营挣的。']);
    else if (r.t.ocfd != null && r.t.ocfd < OCF_MIN + 0.5)
      out.push(['warn', '!', esc(r.name) + ' OCF/分红 仅 ' + fmt(r.t.ocfd, 2) + '，覆盖偏薄。']);
  });

  if (T.mv > 0) {
    const r0 = T.shMv / T.mv * 100;
    if (Math.abs(r0 - 60) > 3) out.push(['warn', '!', '沪市市值占 ' + fmt(r0, 1) + '%，目标 60%，' + (r0 > 60 ? '深市偏少' : '沪市偏少') + '。']);
  }
  // 安全边际：仅对「已持仓」提示（未持仓的目标股属于噪音）；分位偏低=安全垫薄，别追高
  rows.forEach(r => {
    if (r.shares <= 0 || !r.margin) return;
    const p = r.margin.yldPct;
    if (p != null && p <= 20)
      out.push(['warn', '!', esc(r.name) + ' 股息率处近 ' + (CFG && CFG.margin ? CFG.margin.pctYears : 3) + ' 年 ' + fmt(p, 0) + '% 分位（安全垫薄），别追高。']);
    else if (r.boll60 && r.boll60.belowLower && r.margin.yldPct != null && r.margin.yldPct >= 60)
      out.push(['ok', 'i', esc(r.name) + ' 触及布林下轨且股息率分位 ' + fmt(r.margin.yldPct, 0) + '%，是低吸窗口。']);
  });

  // 打新门槛：直接给「距门槛还差 X」，比进度条直观
  if (T.mv > 0) {
    const GATE2 = 10000;
    if (T.shMv < GATE2) out.push(['bad', '×', '沪市市值不足 1 万门槛，还差 ' + fmt(GATE2 - T.shMv, 0) + ' 元。']);
    if (T.szMv < GATE2) out.push(['bad', '×', '深市市值不足 1 万门槛，还差 ' + fmt(GATE2 - T.szMv, 0) + ' 元。']);
  }

  if (!out.length) out.push(['ok', '✓', '结构与目标一致，无越线项。']);

  // 预警分级：红灯（bad）全部置顶高亮；黄灯（warn）/其它折叠成一行「另有 N 项关注」
  const RED = ['bad'];
  const reds = out.filter(a => RED.indexOf(a[0]) >= 0);
  const others = out.filter(a => RED.indexOf(a[0]) < 0);
  const renderAlert = a => '<div class="alert ' + a[0] + '"><span class="ic">' + a[1] + '</span><span>' + a[2] + '</span></div>';
  let html = reds.map(renderAlert).join('');
  if (others.length) {
    if (others.length === 1 && others[0][0] === 'ok') {
      html += renderAlert(others[0]); // 只有一条「正常/低吸」时直接显示
    } else {
      html += '<details class="alert-fold"><summary class="alert warn"><span class="ic">!</span><span>另有 ' + others.length + ' 项关注（点击展开）</span></summary>' +
        others.map(renderAlert).join('') + '</details>';
    }
  }
  $('#alertBox').innerHTML = html;
}

