function updateMarginFoot() {
  const el = document.getElementById('mgFoot');
  if (!el) return;
  const n = marginCount();
  const mgTxt = n
    ? '安全边际指标（股息率目标买价 / 近3年股息率分位 / 布林带下轨）页面内实时计算，已覆盖 ' + n +
      ' 只（行情/分红来自东财公开接口）。数据湖 PE/PB 暂缺，估值分位以股息率分位替代。'
    : '<span class="tx3">安全边际指标加载中/未取到（依赖东财公开接口），暂按 60 日均价口径。</span>';
  el.innerHTML = mgTxt + '<br>' + cfgSyncInfoHtml();
}

/* 配置同步时间差：对比 config.js 的 meta.generated 与库内 cfgSyncedAt */
function cfgSyncInfoHtml() {
  const jsGen = (CFG_FROM_JS && CFG_FROM_JS.meta && CFG_FROM_JS.meta.generated) || null; // 形如 "2026-11-05 15:04"
  const syncedAt = cfgSyncedAt(); // ISO
  const syncedTxt = syncedAt ? syncedAt.slice(0, 16).replace('T', ' ') : (CFG ? '—' : '无');
  let warn = '';
  // config.js 存在且其生成时间晚于库内同步时间 → 提示可能忘了同步
  if (jsGen && syncedAt) {
    const genMs = Date.parse(jsGen.replace(' ', 'T'));
    const syncMs = Date.parse(syncedAt);
    if (isFinite(genMs) && isFinite(syncMs) && genMs > syncMs + 60000) {
      warn = ' <b class="gold">⚠ config.js 已更新，库内配置较旧，请到「设置 → 从 config.js 同步」</b>';
    }
  }
  return '<span class="tx3">目标配置：库内同步于 ' + esc(syncedTxt) +
    (jsGen ? '，config.js 生成于 ' + esc(jsGen) : '') + '</span>' + warn;
}

