/* 导出 CSV（人可读备份，便于年度复查/喂 Python） */
function _csvCell(v) { const s = String(v == null ? '' : v); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; }
function _downloadCsv(name, header, rows) {
  const BOM = '\ufeff'; // 让 Excel 正确识别 UTF-8
  const txt = BOM + [header].concat(rows).map(r => r.map(_csvCell).join(',')).join('\r\n');
  const blob = new Blob([txt], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = name + '_' + new Date().toISOString().slice(0, 10) + '.csv';
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
  toast('已导出 ' + a.download);
}
function exportTradesCsv() {
  const rows = S.trades.slice().sort((a, b) => a.date < b.date ? -1 : a.date > b.date ? 1 : a.id - b.id)
    .map(t => [acctName(t.acct), t.date, realName(t.name, t.code), t.code, SIDES[t.side] || t.side,
      t.shares, t.price, t.fee, (t.shares * t.price).toFixed(2), t.note || '']);
  if (!rows.length) { toast('没有交易流水', true); return; }
  _downloadCsv('交易流水', ['账户', '日期', '名称', '代码', '方向', '股数', '价格', '费用', '成交额', '备注'], rows);
}
function exportDivsCsv() {
  const rows = S.divs.slice().sort((a, b) => a.date < b.date ? -1 : a.date > b.date ? 1 : a.id - b.id)
    .map(d => [acctName(d.acct), d.date, realName(d.name, d.code), d.code, d.amount, d.tax, (d.amount - d.tax).toFixed(2), d.note || '']);
  if (!rows.length) { toast('没有分红记录', true); return; }
  _downloadCsv('分红记录', ['账户', '日期', '名称', '代码', '税前', '扣税', '到账', '备注'], rows);
}
function exportHoldCsv() {
  const rows = rowsNow();
  if (!rows.length) { toast('没有持仓数据', true); return; }
  const data = rows.map(r => [r.name, r.code, r.ind, r.shares, r.costPrice ? r.costPrice.toFixed(4) : '',
    r.price || '', r.mv ? r.mv.toFixed(2) : '', r.pnl != null ? r.pnl.toFixed(2) : '',
    r.pnlRate != null ? r.pnlRate.toFixed(2) + '%' : '', r.divNet ? r.divNet.toFixed(2) : '',
    (r.t && r.t.governance) || '']);
  _downloadCsv('持仓快照', ['名称', '代码', '行业', '数量', '成本价', '现价', '市值', '浮动盈亏', '收益率', '累计分红', '实控人'], data);
}

