$('#btnImportPf').onclick = importPortfolioJs;
$('#btnCsvTrades').onclick = exportTradesCsv;
$('#btnCsvDivs').onclick = exportDivsCsv;
$('#btnCsvHold').onclick = exportHoldCsv;

