const d9 = new SQL.Database();
d9.exec(SCHEMA); P._setDb(d9); P._seedInto(d9); P._readState();
d9.run('INSERT INTO account(id,name,sort) VALUES(?,?,?)', ['b2', '第二账户', 1]);
// #1 跨账户：acct main 与 b2 各买 1000 股同代码（直接用 d9 写入，避免共用 helper 绑定到旧库）
const insTrade = (db, acct, code, name, side, date, sh, px, fee) =>
  db.run('INSERT INTO trade(acct,code,name,side,date,shares,price,fee,note) VALUES(?,?,?,?,?,?,?,?,?)',
    [acct, code, name, side, date, sh, px, fee || 0, '']);
insTrade(d9, 'main', '601000', '唐山港', 'buy', '2026-01-05', 1000, 10, 5);
insTrade(d9, 'b2', '601000', '唐山港', 'buy', '2026-01-06', 1000, 10, 5);
P._readState();
S.active = 'main';
const mainPos = P.positionsNow().filter(x => x.code === '601000')[0];
ok(mainPos && mainPos.shares === 1000, '#1 主账户 601000 持仓 1000（不被 b2 串入）');
S.active = 'ALL';
const allPos = P.positionsNow().filter(x => x.code === '601000')[0];
ok(allPos && allPos.shares === 2000, '#1 全部账户视图合计 2000（校验应按账户拆分）');

// #2 超额卖出：main 买 100@10(fee5)，再塞脏卖出 500@12(fee6)
const d10 = new SQL.Database();
d10.exec(SCHEMA); P._setDb(d10); P._seedInto(d10); P._readState();
insTrade(d10, 'main', '000651', '格力电器', 'buy', '2026-01-05', 100, 10, 5);
insTrade(d10, 'main', '000651', '格力电器', 'sell', '2026-01-06', 500, 12, 6); // 超额
P._readState();
S.active = 'ALL';
const gp = P.positionsNow().filter(x => x.code === '000651')[0];
ok(gp && gp.shares === 0, '#2 超额卖出后股数归零（不为负）');
// 期望 realized = 100*12 - 6*(100/500) - 100*10 = 1200 - 1.2 - 1000 = 198.8
ok(gp && near(gp.realized, 198.8, 0.05), '#2 超额卖出 realized 按实成交 100 股算 → ' + (gp && gp.realized.toFixed(2)) + '（期望 198.8）');
ok(gp && near(gp.sellAmt, 1200, 0.05), '#2 sellAmt 按实成交 → ' + (gp && gp.sellAmt.toFixed(2)) + '（期望 1200，非 6000）');

// #5 治理底线：family/foreign 应出红级预警
const d11 = new SQL.Database();
d11.exec(SCHEMA); P._setDb(d11); P._seedInto(d11); P._readState();
insTrade(d11, 'main', '601000', '唐山港', 'buy', '2026-01-05', 1000, 10, 5);
P._readState();
P.applyConfig({ targets: [{ code: '601000', name: '唐山港', ind: '交运', mkt: '沪', w: 10, governance: 'family', vol: 10 }], rules: sandbox.PANEL_CONFIG.rules, margin: sandbox.PANEL_CONFIG.margin });
S.active = 'ALL';
S.px = { '601000': { price: 10, prev: 10, chg: 0, name: '唐山港', at: Date.now() } };
P.render();
const alertHtml = el('alertBox').innerHTML;
ok(alertHtml.indexOf('宪法第一条') >= 0, '#5 family 实控人触发宪法第一条红色预警');
ok(el('holdBody').innerHTML.indexOf('家族实控') >= 0, '#5 持仓行显示家族实控徽章');

